import { DoorState, TileType, VisibilityState } from './types';

/**
 * Represents a single cell on the 2D dungeon map.
 * Encapsulates passability, line-of-sight transparency, door state, and Fog of War visibility.
 */
export class Tile {
  public type: TileType;
  public doorState: DoorState;
  public visibility: VisibilityState;
  public lastSeenDoorState: DoorState;

  constructor(
    type: TileType,
    doorState: DoorState = type === TileType.DOOR ? DoorState.CLOSED : DoorState.NONE,
    visibility: VisibilityState = VisibilityState.UNEXPLORED
  ) {
    this.type = type;
    this.doorState = type === TileType.DOOR ? doorState : DoorState.NONE;
    this.visibility = visibility;
    this.lastSeenDoorState = this.doorState;
  }

  public static createFloor(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.FLOOR, DoorState.NONE, visibility);
  }

  public static createWall(visibility: VisibilityState = VisibilityState.UNEXPLORED): Tile {
    return new Tile(TileType.WALL, DoorState.NONE, visibility);
  }

  public static createDoor(
    state: DoorState.CLOSED | DoorState.OPEN = DoorState.CLOSED,
    visibility: VisibilityState = VisibilityState.UNEXPLORED
  ): Tile {
    return new Tile(TileType.DOOR, state, visibility);
  }

  /**
   * Whether an actor (player or enemy) can step onto this tile.
   * Floor is passable; Wall is non-passable; Door is passable only when OPEN.
   */
  public isPassable(): boolean {
    switch (this.type) {
      case TileType.FLOOR:
        return true;
      case TileType.WALL:
        return false;
      case TileType.DOOR:
        return this.doorState === DoorState.OPEN;
    }
  }

  /**
   * Whether light / sight can pass through this tile.
   * Floor is transparent; Wall and CLOSED Door block sight; OPEN Door is transparent.
   */
  public isTransparent(): boolean {
    switch (this.type) {
      case TileType.FLOOR:
        return true;
      case TileType.WALL:
        return false;
      case TileType.DOOR:
        return this.doorState === DoorState.OPEN;
    }
  }

  public isDoor(): boolean {
    return this.type === TileType.DOOR;
  }

  public isClosedDoor(): boolean {
    return this.type === TileType.DOOR && this.doorState === DoorState.CLOSED;
  }

  public isOpenDoor(): boolean {
    return this.type === TileType.DOOR && this.doorState === DoorState.OPEN;
  }

  /**
   * Opens a closed door. Returns true if the state changed.
   */
  public openDoor(): boolean {
    if (this.type !== TileType.DOOR || this.doorState !== DoorState.CLOSED) {
      return false;
    }
    this.doorState = DoorState.OPEN;
    if (this.visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = DoorState.OPEN;
    }
    return true;
  }

  /**
   * Closes an open door. Returns true if the state changed.
   */
  public closeDoor(): boolean {
    if (this.type !== TileType.DOOR || this.doorState !== DoorState.OPEN) {
      return false;
    }
    this.doorState = DoorState.CLOSED;
    if (this.visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = DoorState.CLOSED;
    }
    return true;
  }

  /**
   * Updates tile visibility state and records lastSeenDoorState when currently visible.
   */
  public setVisibility(visibility: VisibilityState): void {
    this.visibility = visibility;
    if (visibility === VisibilityState.VISIBLE) {
      this.lastSeenDoorState = this.doorState;
    }
  }
}
