import { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { DirectionVector, Point } from '../types';
import { Action, ActionResult, DASH_ACTION_TIME_COST, DASH_SP_COST } from './Action';

/**
 * Dash movement action (`Ctrl + Arrow Keys` or `Ctrl + Left-Click` on an adjacent walkable tile):
 * - Costs `DASH_SP_COST` (10 SP) and sets `lastActionSpRegenMultiplier = 0` (0% SP recovery that turn).
 * - Moves 2x faster (`DASH_ACTION_TIME_COST = 50` base ticks instead of 100).
 * - Only steps onto an unoccupied passable tile (FLOOR or OPEN door); blocked by walls, CLOSED doors, or actors.
 */
export class DashAction implements Action {
  public readonly type = 'dash';
  public readonly dx: number;
  public readonly dy: number;

  constructor(dx: number, dy: number) {
    this.dx = Math.sign(dx);
    this.dy = Math.sign(dy);
  }

  public static fromDirection(dir: Pick<DirectionVector, 'dx' | 'dy'>): DashAction {
    return new DashAction(dir.dx, dir.dy);
  }

  public execute(actor: Actor, world: GameWorld): ActionResult {
    if (this.dx === 0 && this.dy === 0) {
      return { success: false, timeCost: 0, message: 'No dash direction specified.' };
    }

    if (actor.stats.sp < DASH_SP_COST) {
      const noSpMsg = 'Not enough stamina (SP)!';
      if (actor.isPlayer) {
        world.eventBus.log(noSpMsg, 'combat', world.timeline.currentTime, 'notEnoughStamina', {
          actor: actor.name,
          required: DASH_SP_COST,
        });
      }
      return { success: false, timeCost: 0, message: noSpMsg };
    }

    const target: Point = {
      x: actor.position.x + this.dx,
      y: actor.position.y + this.dy,
    };

    const tile = world.map.getTile(target.x, target.y);
    if (!tile) {
      const message = 'Cannot move outside the dungeon boundary.';
      if (actor.isPlayer) {
        world.eventBus.log(message, 'move', world.timeline.currentTime, 'moveOutsideBoundary');
      }
      return { success: false, timeCost: 0, message };
    }

    const blockingActor = world.getBlockingActorAt(target);
    if ((blockingActor && blockingActor.id !== actor.id) || !tile.isPassable()) {
      const message = 'Cannot dash there — path is blocked!';
      if (actor.isPlayer) {
        world.eventBus.log(message, 'move', world.timeline.currentTime, 'dashBlocked');
      }
      return { success: false, timeCost: 0, message };
    }

    actor.consumeSp(DASH_SP_COST);
    actor.position = target;

    if (actor.isPlayer) {
      const itemsHere = world.getItemsAt(target);
      if (itemsHere.length > 0) {
        const itemsText = itemsHere
          .map((i) => (i.amount > 1 ? `${i.name} x${i.amount}` : i.name))
          .join(', ');
        world.eventBus.log(
          `${actor.name} sees ${itemsText} here.`,
          'info',
          world.timeline.currentTime,
          'seesItemsHere',
          { actor: actor.name, items: itemsText }
        );
      }
    }

    return {
      success: true,
      timeCost: DASH_ACTION_TIME_COST,
    };
  }
}
