import { Enemy } from '../enemies/Enemy';
import { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { DirectionVector, Point } from '../types';
import { Action, ActionResult, DEFAULT_ACTION_TIME_COST } from './Action';
import { DoorAction } from './DoorAction';
import { MeleeAttackAction } from './MeleeAttackAction';

/**
 * Moves an actor to one of the 8 surrounding adjacent tiles:
 * - Allows diagonal movement past wall corners as long as the destination tile itself is passable.
 * - Automatically opens an adjacent CLOSED door when moving into it (if the actor can open doors).
 * - Automatically performs a MeleeAttackAction when moving into an adjacent hostile actor (bump-to-attack).
 */
export class MoveAction implements Action {
  public readonly type = 'move';
  public readonly dx: number;
  public readonly dy: number;

  constructor(dx: number, dy: number) {
    this.dx = Math.sign(dx);
    this.dy = Math.sign(dy);
  }

  public static fromDirection(dir: DirectionVector): MoveAction {
    return new MoveAction(dir.dx, dir.dy);
  }

  public static fromTargetPoint(origin: Point, target: Point): MoveAction {
    return new MoveAction(target.x - origin.x, target.y - origin.y);
  }

  public execute(actor: Actor, world: GameWorld): ActionResult {
    if (this.dx === 0 && this.dy === 0) {
      return { success: false, timeCost: 0, message: 'No movement direction specified.' };
    }

    const target: Point = {
      x: actor.position.x + this.dx,
      y: actor.position.y + this.dy,
    };

    const tile = world.map.getTile(target.x, target.y);
    if (!tile) {
      const message = 'Cannot move outside the dungeon boundary.';
      if (actor.isPlayer) {
        world.eventBus.log(message, 'move', world.timeline.currentTime, 'moveOutsideBoundary');
      }
      return { success: false, timeCost: 0, message };
    }

    // Check if another blocking actor occupies the target tile first (e.g. enemy standing in an open doorway or floor)
    const blockingActor = world.getBlockingActorAt(target);
    if (blockingActor && blockingActor.id !== actor.id) {
      if (actor.isPlayer !== blockingActor.isPlayer) {
        return new MeleeAttackAction(blockingActor).execute(actor, world);
      }
      const message = `${blockingActor.name} is blocking the way.`;
      if (actor.isPlayer) {
        world.eventBus.log(message, 'combat', world.timeline.currentTime, 'blockingTheWay', {
          blocker: blockingActor.name,
        });
      }
      return { success: false, timeCost: 0, message };
    }

    // Auto-open adjacent closed doors when moving/clicking into them (if actor is allowed to open doors)
    if (tile.isClosedDoor()) {
      if (actor instanceof Enemy && !actor.canOpenDoors) {
        return { success: false, timeCost: 0, message: 'Blocked by a closed door.' };
      }
      return new DoorAction(target, 'OPEN').execute(actor, world);
    }

    if (!tile.isPassable()) {
      const message = 'Blocked by a wall.';
      if (actor.isPlayer) {
        world.eventBus.log(message, 'move', world.timeline.currentTime, 'blockedByWall');
      }
      return { success: false, timeCost: 0, message };
    }

    actor.position = target;
    actor.lastActionSpRegenMultiplier = 0.5;
    if (actor.isPlayer) {
      const itemsHere = world.getItemsAt(target);
      if (itemsHere.length > 0) {
        const itemsText = itemsHere
          .map((i) => (i.amount > 1 ? `${i.name} x${i.amount}` : i.name))
          .join(', ');
        world.eventBus.log(
          `${actor.name} sees ${itemsText} here.`,
          'info',
          world.timeline.currentTime,
          'seesItemsHere',
          { actor: actor.name, items: itemsText }
        );
      }
    }
    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
    };
  }
}
