import { MapGeneratorRegistry } from './MapGenerator';
import { MazeGenerator } from './MazeGenerator';
import { RoomsAndCorridorsGenerator } from './RoomsAndCorridorsGenerator';

export * from './MapGenerator';
export * from './RoomsAndCorridorsGenerator';
export * from './MazeGenerator';

export function createDefaultMapGeneratorRegistry(): MapGeneratorRegistry {
  const registry = new MapGeneratorRegistry();
  registry.register(new RoomsAndCorridorsGenerator(), true);
  registry.register(new MazeGenerator(), false);
  return registry;
}
