export { Dog, type DogOptions } from './Dog';

/**
 * Weighted factory for spawning an enemy instance:
 * - 50% Chick (`roll < 0.5`)
 * - 30% Rooster (`0.5 <= roll < 0.8`)
 * - 20% Dog (`roll >= 0.8`)
 */
export function createWeightedEnemy(id: string, position: Point, roll: number): Enemy {
  if (roll < 0.5) {
    return new Chick({ id, position });
  }
  if (roll < 0.8) {
    return new Rooster({ id, position });
  }
  return new Dog({ id, position });
}
