import { ConcreteItemOptions, Item } from './Item';

export interface IronSwordOptions extends ConcreteItemOptions {
  readonly attackBonus?: number;
}

/**
 * Standard forged iron blade that increases physical attack when wielded.
 */
export class IronSword extends Item {
  public readonly attackBonus: number;

  constructor(options: IronSwordOptions) {
    super({
      id: options.id ?? `iron-sword-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Iron Sword',
      itemTypeId: 'iron_sword',
      itemType: 'weapon',
      position: options.position,
      spriteKey: 'item_sword',
      amount: options.amount ?? 1,
      weight: options.weight ?? 4.0,
      stackable: false,
      description:
        options.description ??
        'A well-balanced forged iron blade that grants +4 Physical Attack when equipped.',
    });
    this.attackBonus = options.attackBonus ?? 4;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): IronSword {
    return new IronSword({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      attackBonus: this.attackBonus,
    });
  }
}
