/**
 * Core geometric and domain types for the RogueLike Dungeon Game.
 * Pure TypeScript with zero DOM dependencies.
 */

export interface Point {
  readonly x: number;
  readonly y: number;
}

export enum DirectionName {
  UP = 'UP',
  UP_RIGHT = 'UP_RIGHT',
  RIGHT = 'RIGHT',
  RIGHT_DOWN = 'RIGHT_DOWN',
  DOWN = 'DOWN',
  LEFT_DOWN = 'LEFT_DOWN',
  LEFT = 'LEFT',
  LEFT_UP = 'LEFT_UP',
}

export interface DirectionVector {
  readonly name: DirectionName;
  readonly dx: -1 | 0 | 1;
  readonly dy: -1 | 0 | 1;
}

export const DIRECTIONS: Readonly<Record<DirectionName, DirectionVector>> = {
  [DirectionName.UP]: { name: DirectionName.UP, dx: 0, dy: -1 },
  [DirectionName.UP_RIGHT]: { name: DirectionName.UP_RIGHT, dx: 1, dy: -1 },
  [DirectionName.RIGHT]: { name: DirectionName.RIGHT, dx: 1, dy: 0 },
  [DirectionName.RIGHT_DOWN]: { name: DirectionName.RIGHT_DOWN, dx: 1, dy: 1 },
  [DirectionName.DOWN]: { name: DirectionName.DOWN, dx: 0, dy: 1 },
  [DirectionName.LEFT_DOWN]: { name: DirectionName.LEFT_DOWN, dx: -1, dy: 1 },
  [DirectionName.LEFT]: { name: DirectionName.LEFT, dx: -1, dy: 0 },
  [DirectionName.LEFT_UP]: { name: DirectionName.LEFT_UP, dx: -1, dy: -1 },
};

export const ALL_DIRECTIONS: readonly DirectionVector[] = Object.values(DIRECTIONS);

export enum TileType {
  FLOOR = 'FLOOR',
  WALL = 'WALL',
  DOOR = 'DOOR',
}

export enum DoorState {
  NONE = 'NONE',
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
}

export enum VisibilityState {
  UNEXPLORED = 'UNEXPLORED',
  EXPLORED = 'EXPLORED',
  VISIBLE = 'VISIBLE',
}

export const DEFAULT_SIGHT_RADIUS = 8;
export const DEFAULT_TILE_SIZE = 32;

export function pointsEqual(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y;
}

export function isAdjacent(a: Point, b: Point): boolean {
  const dx = Math.abs(a.x - b.x);
  const dy = Math.abs(a.y - b.y);
  return Math.max(dx, dy) === 1;
}
