import { ConcreteItemOptions, Item } from './Item';

export interface MagicScrollOptions extends ConcreteItemOptions {
  readonly spellPower?: number;
}

/**
 * Consumable parchment inscribed with arcane runes.
 */
export class MagicScroll extends Item {
  public readonly spellPower: number;

  constructor(options: MagicScrollOptions) {
    super({
      id: options.id ?? `magic-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Magic Scroll',
      itemTypeId: 'magic_scroll',
      itemType: 'consumable',
      position: options.position,
      spriteKey: 'item_scroll',
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      stackable: true,
      description:
        options.description ??
        'An ancient parchment inscribed with arcane runes that unleashes magical energy when read.',
    });
    this.spellPower = options.spellPower ?? 15;
  }

  public override cloneWithAmount(newAmount: number, newId?: string): MagicScroll {
    return new MagicScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      spellPower: this.spellPower,
    });
  }
}
