import { Actor } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { DoorState, isAdjacent, Point, TileType } from '../types';
import { Action, ActionResult, DEFAULT_ACTION_TIME_COST } from './Action';

export type DoorOperation = 'OPEN' | 'CLOSE' | 'TOGGLE';

/**
 * Opens or closes an adjacent door tile.
 * - Cannot interact with a door that is not on one of the 8 surrounding adjacent tiles.
 * - Cannot close an open door if any entity (actor or item) is currently on that door tile.
 */
export class DoorAction implements Action {
  public readonly type = 'door';
  public readonly targetPosition: Point;
  public readonly operation: DoorOperation;

  constructor(targetPosition: Point, operation: DoorOperation = 'TOGGLE') {
    this.targetPosition = { x: targetPosition.x, y: targetPosition.y };
    this.operation = operation;
  }

  public execute(actor: Actor, world: GameWorld): ActionResult {
    if (!isAdjacent(actor.position, this.targetPosition)) {
      const message = 'That door is too far away.';
      world.eventBus.log(message, 'door', world.timeline.currentTime, 'doorTooFar');
      return { success: false, timeCost: 0, message };
    }

    const tile = world.map.getTile(this.targetPosition.x, this.targetPosition.y);
    if (!tile || tile.type !== TileType.DOOR) {
      const message = 'There is no door there.';
      world.eventBus.log(message, 'door', world.timeline.currentTime, 'noDoorThere');
      return { success: false, timeCost: 0, message };
    }

    const resolvedOp: 'OPEN' | 'CLOSE' =
      this.operation === 'TOGGLE'
        ? tile.doorState === DoorState.CLOSED
          ? 'OPEN'
          : 'CLOSE'
        : this.operation;

    if (resolvedOp === 'OPEN') {
      if (tile.doorState === DoorState.OPEN) {
        const message = 'The door is already open.';
        world.eventBus.log(message, 'door', world.timeline.currentTime, 'doorAlreadyOpen');
        return { success: false, timeCost: 0, message };
      }

      tile.openDoor();
      actor.lastActionSpRegenMultiplier = 0.5;
      const message = `${actor.name} opens the door.`;
      world.eventBus.log(message, 'door', world.timeline.currentTime, 'opensDoor', {
        actor: actor.name,
      });
      return {
        success: true,
        timeCost: DEFAULT_ACTION_TIME_COST,
        message,
      };
    } else {
      if (tile.doorState === DoorState.CLOSED) {
        const message = 'The door is already closed.';
        world.eventBus.log(message, 'door', world.timeline.currentTime, 'doorAlreadyClosed');
        return { success: false, timeCost: 0, message };
      }

      if (world.hasAnyEntityAt(this.targetPosition)) {
        const message = 'Cannot close the door while something is in the doorway.';
        world.eventBus.log(message, 'door', world.timeline.currentTime, 'doorBlockedByEntity');
        return { success: false, timeCost: 0, message };
      }

      tile.closeDoor();
      actor.lastActionSpRegenMultiplier = 0.5;
      const message = `${actor.name} closes the door.`;
      world.eventBus.log(message, 'door', world.timeline.currentTime, 'closesDoor', {
        actor: actor.name,
      });
      return {
        success: true,
        timeCost: DEFAULT_ACTION_TIME_COST,
        message,
      };
    }
  }
}
