import { Action, MELEE_SP_COST, WaitAction } from '../actions/Action';
import { MeleeAttackAction } from '../actions/MeleeAttackAction';
import { MoveAction } from '../actions/MoveAction';
import { Actor, ActorStats, PrimaryAttributes } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { findShortestPathForEnemy } from '../Pathfinder';
import { isAdjacent, Point } from '../types';

export const DEFAULT_ENEMY_SENSING_RANGE = 6;
export const DEFAULT_ENEMY_SCORE_VALUE = 25;

/**
 * Optional strategy interface for custom enemy decision-making during their timeline turn.
 */
export interface AIController {
  decideNextAction(enemy: Enemy, world: GameWorld): Action;
}

export interface EnemyArchetype {
  readonly archetypeId: string;
  readonly name: string;
  readonly spriteKey: string;
  readonly sensingRange?: number;
  readonly canOpenDoors?: boolean;
  readonly scoreValue?: number;
  readonly attributes?: Partial<PrimaryAttributes>;
  readonly stats?: Partial<ActorStats>;
  readonly aiController?: AIController;
}

export interface EnemyProps {
  readonly id: string;
  readonly archetypeId: string;
  readonly name: string;
  readonly position: Point;
  readonly spriteKey: string;
  readonly sensingRange?: number;
  readonly canOpenDoors?: boolean;
  readonly scoreValue?: number;
  readonly attributes?: Partial<PrimaryAttributes>;
  readonly stats?: Partial<ActorStats>;
  readonly aiController?: AIController;
}

/**
 * Base Enemy class (`src/core/enemies/Enemy.ts`) providing:
 * - `sensingRange`: Detection radius (Chebyshev distance) for spotting and pursuing the player.
 * - `canOpenDoors`: Whether the enemy can open/close DOOR tiles (false for Chick, Rooster, Dog).
 * - `scoreValue`: Score points awarded when the enemy is defeated.
 * - Default AI (`decideNextAction`):
 *   - Outside `sensingRange` (or when no path exists): Roams randomly (75% step to random adjacent passable tile, 25% wait).
 *   - Inside `sensingRange`: Follows the shortest 8-way A* path toward the player and melee attacks when adjacent.
 */
export class Enemy extends Actor {
  public readonly archetypeId: string;
  public readonly sensingRange: number;
  public readonly canOpenDoors: boolean;
  public readonly scoreValue: number;
  public aiController?: AIController;

  constructor(props: EnemyProps);
  constructor(id: string, position: Point, archetype: EnemyArchetype);
  constructor(
    idOrProps: string | EnemyProps,
    position?: Point,
    archetype?: EnemyArchetype
  ) {
    const resolved: EnemyProps =
      typeof idOrProps === 'string'
        ? {
            id: idOrProps,
            position: position!,
            archetypeId: archetype!.archetypeId,
            name: archetype!.name,
            spriteKey: archetype!.spriteKey,
            sensingRange: archetype!.sensingRange,
            canOpenDoors: archetype!.canOpenDoors,
            scoreValue: archetype!.scoreValue,
            attributes: archetype!.attributes,
            stats: archetype!.stats,
            aiController: archetype!.aiController,
          }
        : idOrProps;

    super({
      id: resolved.id,
      name: resolved.name,
      position: resolved.position,
      spriteKey: resolved.spriteKey,
      isPlayer: false,
      attributes: resolved.attributes,
      stats: resolved.stats,
    });

    this.archetypeId = resolved.archetypeId;
    this.sensingRange = Math.max(0, resolved.sensingRange ?? DEFAULT_ENEMY_SENSING_RANGE);
    this.canOpenDoors = resolved.canOpenDoors ?? false;
    this.scoreValue = Math.max(0, resolved.scoreValue ?? DEFAULT_ENEMY_SCORE_VALUE);
    this.aiController = resolved.aiController;
  }

  /**
   * Determines the enemy's next action on the timeline:
   * 1. Delegates to `this.aiController` if a custom AIController is attached.
   * 2. If the player is alive and within `this.sensingRange`:
   *    - Attacks immediately with `MeleeAttackAction` if adjacent to the player.
   *    - Otherwise steps along the shortest 8-way path toward `player.position` (respecting `canOpenDoors`).
   * 3. Otherwise (outside `sensingRange` or blocked by closed doors/walls):
   *    - Roams by stepping onto a random valid adjacent passable tile (75% chance) or waiting 1 turn (25% chance).
   */
  public decideNextAction(world: GameWorld): Action {
    if (this.aiController) {
      return this.aiController.decideNextAction(this, world);
    }

    if (world.player.isAlive()) {
      const chebyshevDist = Math.max(
        Math.abs(this.position.x - world.player.position.x),
        Math.abs(this.position.y - world.player.position.y)
      );

      if (chebyshevDist <= this.sensingRange) {
        if (isAdjacent(this.position, world.player.position)) {
          if (this.stats.sp >= MELEE_SP_COST) {
            return new MeleeAttackAction(world.player);
          }
          return new WaitAction();
        }

        const path = findShortestPathForEnemy(
          world,
          this.position,
          world.player.position,
          this.canOpenDoors
        );
        if (path && path.length > 0) {
          return MoveAction.fromTargetPoint(this.position, path[0]);
        }
      }
    }

    return this.decideRoamAction(world);
  }

  /**
   * Default roaming behavior when the player is outside `sensingRange` (or unreachable):
   * - Collects all unoccupied adjacent tiles that this enemy can step onto.
   * - Waits 1 turn if boxed in or on a 25% idle roll; otherwise moves to a random valid adjacent tile.
   */
  protected decideRoamAction(world: GameWorld): Action {
    const candidates = world.map.getAdjacentPoints(this.position, true).filter((pt) => {
      const tile = world.map.getTile(pt.x, pt.y);
      if (!tile) {
        return false;
      }
      const canTraverseTile =
        tile.isPassable() || (this.canOpenDoors && tile.isClosedDoor());
      if (!canTraverseTile) {
        return false;
      }
      return world.getBlockingActorAt(pt) === null;
    });

    if (candidates.length === 0 || world.nextRandom() < 0.25) {
      return new WaitAction();
    }

    const chosenIndex = Math.floor(world.nextRandom() * candidates.length);
    const chosenPoint = candidates[Math.min(candidates.length - 1, Math.max(0, chosenIndex))];
    return MoveAction.fromTargetPoint(this.position, chosenPoint);
  }
}
